using Quadrant.Core.Enums; using Quadrant.Core.Interfaces; using Quadrant.Core.Models; using Quadrant.Core.Services; using Xunit;
namespace Quadrant.Core.Tests;
public sealed class FocusTimerServiceTests
{
 [Fact] public async Task Stopwatch_accumulates_only_running_segments_and_floors_seconds(){var c=new Clock();var s=new Sessions(c);var t=new FocusTimerService(s,c);await t.StartAsync(new FocusSessionStartRequest(null,FocusMode.Stopwatch));c.Advance(10.9);Assert.Equal(10,t.GetSnapshot()!.ElapsedSeconds);await t.PauseCurrentAsync();c.Advance(300);Assert.Equal(10,t.GetSnapshot()!.ElapsedSeconds);await t.ResumeCurrentAsync();c.Advance(7.2);var done=await t.StopCurrentAsync();Assert.Equal(17,done.DurationSeconds);Assert.Equal(1,s.CompleteCalls);}
 private sealed class Clock:IClock {public DateTimeOffset UtcNow{get;private set;}=DateTimeOffset.UtcNow;public DateTimeOffset LocalNow=>UtcNow;public DateOnly LocalDate=>DateOnly.FromDateTime(UtcNow.Date);public TimeZoneInfo LocalTimeZone=>TimeZoneInfo.Utc;public long Tick{get;private set;}public void Advance(double s){UtcNow=UtcNow.AddSeconds(s);Tick+=(long)(s*1000);}public long GetTimestamp()=>Tick;public TimeSpan GetElapsedTime(long a,long b)=>TimeSpan.FromMilliseconds(b-a);}
 private sealed class Sessions(Clock c):IFocusSessionService {FocusSession? x;public int CompleteCalls;public Task<FocusSession> StartAsync(FocusSessionStartRequest r,CancellationToken ct=default)=>Task.FromResult(x=new("x",null,r.Mode,c.UtcNow,c.UtcNow,null,null,0,FocusStatus.Running,null,c.LocalDate,null,null));public Task<FocusSession?> GetCurrentAsync(CancellationToken ct=default)=>Task.FromResult(x);public Task<IReadOnlyList<FocusSession>> GetRecentAsync(int l=5,CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<FocusSession>>([]);public Task<FocusSession> PauseAsync(string id,int d,DateTimeOffset a,CancellationToken ct=default)=>Task.FromResult(x=x! with{Status=FocusStatus.Paused,DurationSeconds=d,ActiveSegmentStartedAtUtc=null});public Task<FocusSession> ResumeAsync(string id,DateTimeOffset a,CancellationToken ct=default)=>Task.FromResult(x=x! with{Status=FocusStatus.Running,ActiveSegmentStartedAtUtc=a});public Task<FocusSession> CompleteAsync(string id,int d,DateTimeOffset a,CancellationToken ct=default){CompleteCalls++;return Task.FromResult(x=x! with{Status=FocusStatus.Completed,DurationSeconds=d});}public Task<FocusSession> InterruptAsync(string i,int d,DateTimeOffset a,CancellationToken ct=default)=>throw new NotImplementedException();public Task<FocusSession> CancelAsync(string i,int d,DateTimeOffset a,CancellationToken ct=default)=>Task.FromResult(x=x! with{Status=FocusStatus.Cancelled,DurationSeconds=d});}
}
